// Filter applies the PerformerWhereInput filter on the PerformerQuery builder.
func (i *PerformerWhereInput) Filter(q *PerformerQuery) (*PerformerQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyPerformerWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

